export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed);
  const g = Number(inputs.gravity);
  const tApex = u / g;
  const hApex = (u * u) / (2 * g);
  const t = Number(time);

  let yToss = u * t - 0.5 * g * t * t;
  if (yToss < 0) yToss = 0;
  const vToss = t <= (2 * u) / g ? u - g * t : 0;
  const aToss = t <= (2 * u) / g ? -g : 0;

  const gateOpen = t >= tApex;
  let yDrop = hApex;
  let vDrop = 0;
  let aDrop = 0;
  if (t > tApex) {
    const dt = t - tApex;
    yDrop = hApex - 0.5 * g * dt * dt;
    if (yDrop < 0) yDrop = 0;
    vDrop = -g * dt;
    aDrop = -g;
  }

  let tossState = "At launch";
  if (Math.abs(t - tApex) < 0.02) tossState = "At the top";
  else if (t > 0 && t < tApex) tossState = "Rising";
  else if (t > tApex && yToss > 0) tossState = "Falling";
  else if (yToss <= 0 && t > tApex) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - tApex) < 0.02) dropState = "Just released";
  else if (t > tApex && yDrop > 0) dropState = "Falling together";
  else if (yDrop <= 0 && t > tApex) dropState = "At launch height";

  const pxPerMeter = 120;
  const y0 = 360;
  const tossX = 160;
  const dropX = 480;

  const tossCenterY = y0 - yToss * pxPerMeter;
  const dropCenterY = y0 - yDrop * pxPerMeter;
  const apexY = y0 - hApex * pxPerMeter;

  const objects = [];

  const tossPanel = sdk.panel({ x: 30, y: 30, w: 260, h: 360, title: "Toss Lane", state: tossState, id: "lane.toss" });
  const dropPanel = sdk.panel({ x: 350, y: 30, w: 260, h: 360, title: "Drop Lane", state: dropState, id: "lane.drop" });
  objects.push(...tossPanel, ...dropPanel);

  objects.push(sdk.axis("axis.toss", { x: 60, y: y0, length: 280, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: 380, y: y0, length: 280, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  objects.push(...sdk.gate("gate", dropX, apexY, { open: gateOpen, w: 40, label: "Apex Gate" }));

  if (gateOpen) {
    objects.push(sdk.circle("ghost.toss", tossX, apexY, 24, { opacity: 0.35, role: "neutral" }));
    objects.push(sdk.circle("ghost.drop", dropX, apexY, 24, { opacity: 0.35, role: "neutral" }));
  }

  objects.push(sdk.circle("ball.toss", tossX, tossCenterY, 28, { role: "learner" }));
  objects.push(sdk.circle("ball.drop", dropX, dropCenterY, 28, { role: "prediction" }));

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 22, y: tossCenterY }, { value: vToss, direction: "up", scale: 18, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 22, y: tossCenterY }, { value: aToss, direction: "up", scale: 12, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 22, y: dropCenterY }, { value: vDrop, direction: "up", scale: 18, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 22, y: dropCenterY }, { value: aDrop, direction: "up", scale: 12, label: "a" }));

  const tossLines = [`v = ${sdk.format(vToss, 2)} m/s`, `a = ${sdk.format(aToss, 2)} m/s²`];
  const dropLines = [`v = ${sdk.format(vDrop, 2)} m/s`, `a = ${sdk.format(aDrop, 2)} m/s²`];
  objects.push(...sdk.callout(tossX + 40, tossCenterY - 20, tossLines, { id: "callout.toss" }));
  objects.push(...sdk.callout(dropX + 40, dropCenterY - 20, dropLines, { id: "callout.drop" }));

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: tApex,
    apexHeight: hApex,
    tossedVelocity: vToss,
    tossedAcceleration: aToss,
    tossedHeight: yToss,
    dropVelocity: vDrop,
    dropAcceleration: aDrop,
    dropHeight: yDrop
  };

  const readouts = [
    { id: "tossedVelocity", value: vToss },
    { id: "tossedAcceleration", value: aToss },
    { id: "dropVelocity", value: vDrop },
    { id: "dropAcceleration", value: aDrop }
  ];

  return {
    frame: sdk.frame(objects, { width: 640, height: 420, readouts }),
    quantities
  };
}
